import { css, FlattenSimpleInterpolation } from 'styled-components';

/** Applies cell styled alignment. */
export function columnAlignmentCss({
  $alignment,
}: {
  $alignment: 'left' | 'center' | 'right';
}): FlattenSimpleInterpolation {
  return css({
    textAlign: $alignment,
  });
}

/** Applies cell styled alignment. */
export function columnAlignmentHeaderCss({
  $alignment,
}: {
  $alignment: 'left' | 'center' | 'right';
}): FlattenSimpleInterpolation {
  if ($alignment === 'center') {
    return css`
      justify-content: center;
    `;
  }
  if ($alignment === 'right') {
    return css`
      justify-content: flex-end;
    `;
  }
  return css`
    justify-content: flex-start;
  `;
}
